using Azure.AI.OpenAI;
using Azure.Identity;
using OpenAI;

namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Resolves the same IChatClient the app uses.
    /// Detected: AddAzureOpenAIChatClient at AppHost.cs:2
    /// Deployment alias: "chat" → gpt-4o-mini
    /// </summary>
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        var connectionString = builder.Configuration.GetConnectionString("chat");
        if (string.IsNullOrEmpty(connectionString))
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but ConnectionStrings:chat is not configured. " +
                "The app uses AddAzureOpenAIChatClient(\"chat\"). Wire one of:\n" +
                "  dotnet user-secrets init --project MyApp.Evals.Tests\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "  # Or Entra-ID (no key):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" --project MyApp.Evals.Tests");
        }

        // Parse connection string: Endpoint=...;Key=...;DeploymentId=...
        var parts = connectionString.Split(';')
            .Select(p => p.Split('=', 2))
            .Where(p => p.Length == 2)
            .ToDictionary(p => p[0].Trim(), p => p[1].Trim(), StringComparer.OrdinalIgnoreCase);

        var endpoint = parts.GetValueOrDefault("Endpoint")
            ?? throw new InvalidOperationException("ConnectionStrings:chat must contain Endpoint=<url>");
        var deploymentId = parts.GetValueOrDefault("DeploymentId") ?? "chat";

        OpenAIClient client;
        if (parts.TryGetValue("Key", out var key) && !string.IsNullOrEmpty(key))
            client = new AzureOpenAIClient(new Uri(endpoint), new System.ClientModel.ApiKeyCredential(key));
        else
            client = new AzureOpenAIClient(new Uri(endpoint), new DefaultAzureCredential());

        return client.GetChatClient(deploymentId).AsIChatClient();
    }
}

